#include <iostream>
#include <stack>
#include <string>
#include <unordered_map>
using namespace std;

bool isValid(const string& s) {
    stack<char> st;
    unordered_map<char, char> pairMap = {{')', '('}, {']', '['}, {'}', '{'}};
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);  // 左括号入栈
        } else {
            if (st.empty() || st.top() != pairMap[c]) return false;
            st.pop();     // 匹配则弹出
        }
    }
    return st.empty();
}

int main() {
    cout << isValid("{[()]}") << endl;  // 1 (true)
    cout << isValid("{[}]")   << endl;  // 0 (false)
    return 0;
}
