#include <stdexcept>
using namespace std;

double divide(double a, double b) {
    if (b == 0) throw runtime_error("division by zero");
    return a / b;
}

int main() {
    try {
        cout << divide(10, 2) << endl;  // 5
        cout << divide(5, 0)  << endl;  // 抛出
    } catch (const runtime_error& e) {
        cout << "异常: " << e.what() << endl;
    }
    return 0;
}
