    map<int, string> rank;   // 积分 -> 玩家名
    rank[100] = "Tom";
    rank[200] = "Sam";
    rank[150] = "Lily";
    cout << "排行榜(自动按积分升序): ";
    for (auto& p : rank) cout << p.first << ":" << p.second << " ";
    cout << endl;

    // 场景 2：仅做 O(1) 单点查询（缓存、词频） -> unordered_map
    unordered_map<string, int> cache;
    cache["apple"] = 1;
    cout << "apple = " << cache["apple"] << endl;
    return 0;
}
