#include <iostream>
#include <unordered_map>
using namespace std;

struct Point {
    int x, y;
    bool operator==(const Point& o) const {
        return x == o.x && y == o.y;
    }
};

// std::hash 特化（必须在 std 命名空间）
namespace std {
template <>
struct hash<Point> {
    size_t operator()(const Point& p) const noexcept {
        // 一种常见组合：异或 + 移位 + 乘质数
        return hash<int>()(p.x) * 31u + hash<int>()(p.y);
    }
};
}

int main() {
    unordered_map<Point, int> mp;
    mp[{1, 2}] = 100;
    mp[{3, 4}] = 200;

    Point key{1, 2};
    cout << "(1,2) -> " << mp[key] << endl;  // 100
    return 0;
}
