#include <iostream>
#include <vector>
#include <deque>
#include <map>
#include <unordered_map>
using namespace std;

int main() {
    // 1. vector
    vector<int> v = {1,2,3,4};
    for (auto it = v.begin(); it != v.end(); ) {
        if (*it % 2 == 0) it = v.erase(it);
        else ++it;
    }

    // 2. deque
    deque<int> d = {1,2,3,4};
    for (auto it = d.begin(); it != d.end(); ) {
        if (*it % 2 == 0) it = d.erase(it);
        else ++it;
    }

    // 3. map
    map<int,int> m = {{1,1},{2,2},{3,3}};
    for (auto it = m.begin(); it != m.end(); ) {
        if (it->second % 2 == 0) it = m.erase(it);
        else ++it;
    }

    // 4. unordered_map
    unordered_map<int,int> u = {{1,1},{2,2},{3,3}};
    for (auto it = u.begin(); it != u.end(); ) {
        if (it->second % 2 == 0) it = u.erase(it);
        else ++it;
    }
    cout << "四种容器均删除完毕" << endl;
    return 0;
}
