#include <iostream>
#include <queue>
#include <vector>
#include <functional>
using namespace std;

int main() {
    // 方法 1：使用 greater<int>
    priority_queue<int, vector<int>, greater<int>> min_pq;
    for (int x : {3, 1, 4, 1, 5, 9, 2, 6}) min_pq.push(x);
    cout << "小顶堆弹出: ";
    while (!min_pq.empty()) {
        cout << min_pq.top() << " ";
        min_pq.pop();
    }
    cout << endl;  // 1 1 2 3 4 5 6 9

    // 方法 2：取负数放入大顶堆
    priority_queue<int> pq;
    for (int x : {3, 1, 4, 1, 5}) pq.push(-x);
    cout << "取负小顶: ";
    while (!pq.empty()) {
        cout << -pq.top() << " ";
        pq.pop();
    }
    cout << endl;  // 1 1 3 4 5
    return 0;
}
