#include <iostream>
#include <list>
using namespace std;

int main() {
    list<int> L1 = {1, 2, 3};
    list<int> L2 = {4, 5, 6};

    // 把 L2 全部拼接到 L1 末尾
    L1.splice(L1.end(), L2);
    cout << "L1: ";
    for (int x : L1) cout << x << " ";  // 1 2 3 4 5 6
    cout << endl;
    cout << "L2 size = " << L2.size() << endl;  // 0，已搬空

    // 区间 splice：把 L3 中的一部分拼到 L1 中
    list<int> L3 = {10, 20, 30, 40};
    auto first = L3.begin();
    ++first;            // 20
    auto last = first;
    advance(last, 2);   // 20, 30, 40 -> [20,40)
    L1.splice(L1.begin(), L3, first, last);
    cout << "L1: ";
    for (int x : L1) cout << x << " ";  // 20 30 1 2 3 4 5 6
    cout << endl;
    return 0;
}
